import{_ as t,o as n,c as a,ah as i}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Activités élargies","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/extended-modules.md","filePath":"src/guide/extended-modules.md"}'),s={name:"guide/extended-modules.md"};function r(o,e,l,u,d,c){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="activites-elargies" tabindex="-1">Activités élargies <a class="header-anchor" href="#activites-elargies" aria-label="Permalink to &quot;Activités élargies&quot;">​</a></h1><p>Les modules 19 à 28, 30, 31 et 33 prolongent le socle sans le conditionner. Ils s&#39;adressent à des populations et des acteurs distincts, mais réutilisent les mêmes comptes, la même facturation et les mêmes documents.</p><h2 id="formation-b2b-sur-devis-module-19" tabindex="-1">Formation B2B sur devis (module 19) <a class="header-anchor" href="#formation-b2b-sur-devis-module-19" aria-label="Permalink to &quot;Formation B2B sur devis (module 19)&quot;">​</a></h2><p>Une entreprise demande une formation pour ses salariés depuis le site NextBoxx (API) ou depuis « Mes demandes entreprise ». La demande <code>DEM-NB</code> porte la raison sociale, le référentiel, le format, l&#39;effectif et la date souhaitée.</p><ol><li>Le <strong>Coordinateur pédagogique</strong> envoie un devis <code>DEV-NB</code> en PDF : référentiel, format, effectif, dates, rythme, montant total. Au-delà de 15 apprenants, une cohorte par tranche de 15.</li><li>Le contact accepte ou refuse le devis dans son espace ; le Coordinateur peut enregistrer l&#39;acceptation pour lui.</li><li>À l&#39;acceptation, les <strong>cohortes dédiées</strong> sont ouvertes au nom de l&#39;entreprise, sans promotion, et une <strong>facture unique</strong> du montant du devis est émise, échue au premier jour de la formation.</li><li>Le contact ou le Coordinateur ajoute les salariés dans la limite des 15 places. Compte créé ou réutilisé, inscription active d&#39;emblée, rôle Apprenant, livret et accès Sève. Ni candidature, ni convention, ni facture individuelle.</li></ol><p>En cas d&#39;impayé, les inscriptions des cohortes dédiées et leur accès Sève sont suspendus à J+30, puis rétablis au paiement. La condition « soldé » d&#39;un apprenant B2B est la facture de la demande payée.</p><h2 id="mise-en-relation-et-recrutement-modules-23-a-26" tabindex="-1">Mise en relation et recrutement (modules 23 à 26) <a class="header-anchor" href="#mise-en-relation-et-recrutement-modules-23-a-26" aria-label="Permalink to &quot;Mise en relation et recrutement (modules 23 à 26)&quot;">​</a></h2><p>Une organisation dépose une demande de <strong>mise en relation</strong> (stage, alternance, mission) ou de <strong>recrutement</strong> (CDI, CDD) depuis « Mes demandes entreprise ». Le formulaire n&#39;affiche que les champs du type choisi.</p><ul><li>Seul un titulaire d&#39;un <strong>certificat NextBoxx</strong> peut se rendre visible des entreprises, avec un CV PDF et une présentation courte.</li><li>Le <strong>Chargé de partenariats</strong> propose des profils visibles, en une ou plusieurs fois.</li><li>L&#39;organisation voit le prénom et l&#39;initiale du nom, les certificats et la présentation. Un profil retenu révèle le nom, l&#39;email, le téléphone et le CV, et l&#39;apprenant est prévenu.</li><li>Dès qu&#39;un profil est retenu, le Chargé confirme la mise en relation : une facture est émise au contact, échue à 30 jours, par profil retenu, avec le forfait de mise en relation et, si demandé, le forfait d&#39;accompagnement.</li><li>Sans les deux forfaits fixés par l&#39;Administrateur, la confirmation est impossible. L&#39;impayé suit les relances et le moratoire, sans suspension.</li></ul><h2 id="evenements-modules-20-a-22" tabindex="-1">Événements (modules 20 à 22) <a class="header-anchor" href="#evenements-modules-20-a-22" aria-label="Permalink to &quot;Événements (modules 20 à 22)&quot;">​</a></h2><p>Le <strong>Chargé d&#39;événements</strong> et l&#39;Administrateur créent un événement (intitulé, présentation, dates, lieu, places, tarif en FCFA, 0 pour gratuit), le publient, le modifient et l&#39;annulent tant qu&#39;il n&#39;a pas commencé. Statuts : <strong>brouillon</strong>, <strong>publié</strong>, <strong>annulé</strong>.</p><ul><li>Inscription par le site (API) ou depuis « Mes événements » ; rôle <strong>Participant</strong> ajouté.</li><li>Refus pour un compte organisation, un compte déjà inscrit, un événement fermé, ou un compte suspendu sur un événement payant.</li><li>Les inscriptions confirmées et en attente de paiement tiennent une place ; au-delà, <strong>liste d&#39;attente</strong>. Une place libérée passe au premier inscrit, qui est prévenu.</li><li>Événement payant : facture <code>FAC-NB</code> à l&#39;inscription, échue <strong>48 h avant le début</strong>. Le paiement complet confirme. Sans paiement à 48 h, l&#39;inscription est annulée, le reste dû annulé par avoir, et la place libérée.</li><li>Un événement gratuit confirme immédiatement et prend des inscriptions jusqu&#39;à son début.</li><li>Annulation : chaque inscrit est prévenu ; le payé est remboursé par avoir, le reste dû annulé.</li></ul><p>Les factures d&#39;événement n&#39;entrent ni dans le calendrier de facturation, ni dans les relances de formation, ni dans les commissions, ni dans les tableaux de bord Direction et Reporting.</p><h2 id="financement-des-evenements-modules-27-et-28" tabindex="-1">Financement des événements (modules 27 et 28) <a class="header-anchor" href="#financement-des-evenements-modules-27-et-28" aria-label="Permalink to &quot;Financement des événements (modules 27 et 28)&quot;">​</a></h2><p>Un <strong>Financeur d&#39;événement</strong> déclare un apport depuis « Mes financements » : événement, nature (financier, en nature, autre), description, montant en FCFA. Le Chargé d&#39;événements peut aussi saisir un apport pour un compte, même après la fin.</p><ul><li>Un apport reste <strong>déclaré</strong> jusqu&#39;à la validation du Chargé, qui constate sa réception avec la date. Il n&#39;est jamais compté automatiquement.</li><li>Le Chargé peut le refuser avec un motif. Aucune facture n&#39;est émise.</li><li>La validation émet la <strong>convention de financement</strong> <code>CONVE-NB-AAAA-XXX</code>, envoyée au financeur, sans signature électronique.</li><li>Le Chargé saisit les <strong>dépenses</strong> de l&#39;événement (libellé, montant, date, justificatif facultatif). Il peut les corriger ou les supprimer.</li><li><strong>Solde net</strong> = apports reçus − dépenses. Le financeur voit le total de ses apports, les dépenses de l&#39;événement et le solde net, sans le détail des autres financeurs.</li><li>À l&#39;annulation de l&#39;événement, les apports déclarés sont annulés ; les apports reçus restent au bilan et leur financeur est prévenu.</li></ul><h2 id="l-eclosion-modules-30-et-31" tabindex="-1">L&#39;Éclosion (modules 30 et 31) <a class="header-anchor" href="#l-eclosion-modules-30-et-31" aria-label="Permalink to &quot;L&#39;Éclosion (modules 30 et 31)&quot;">​</a></h2><p>Le <strong>Chargé d&#39;incubation</strong> crée un cycle en brouillon (titre, clôture des dépôts, début et fin), puis l&#39;ouvre. Les dépôts ferment au plus tard au début de l&#39;incubation.</p><ul><li>Tout compte candidate une fois par cycle : nom du projet, secteur, problème, solution, avancement, pitch PDF facultatif. La voie <strong>Canopé</strong> n&#39;est proposée qu&#39;à un compte au statut Canopé ; les autres candidatent comme porteur externe.</li><li>Le Chargé saisit les <strong>lauréats de concours</strong> pour leur compte, avec le nom et l&#39;année du concours.</li><li>Le Chargé <strong>retient</strong> ou <strong>refuse</strong> avec un motif. Un projet retenu donne le rôle <strong>Porteur de projet</strong>.</li><li>Le Chargé propose une <strong>participation</strong> : capital ou chiffre d&#39;affaires, pourcentage et conditions.</li><li>Le <strong>comité d&#39;investissement</strong> vote à l&#39;unanimité : la proposition vaut vote du Chargé, puis le Coordinateur pédagogique et la Direction votent, chacun depuis un compte différent. Un vote contre motive un refus ; une nouvelle proposition peut alors être faite.</li></ul><h2 id="partenariats-technologiques-module-33" tabindex="-1">Partenariats technologiques (module 33) <a class="header-anchor" href="#partenariats-technologiques-module-33" aria-label="Permalink to &quot;Partenariats technologiques (module 33)&quot;">​</a></h2><p>Le <strong>Chargé de partenariats</strong> ou l&#39;Administrateur saisit un partenariat en négociation : organisation, solution, nature (intégration pédagogique, certification, fourniture d&#39;outils), référentiels concernés, contact signataire, date de fin facultative.</p><ul><li>Le partenariat est <strong>gratuit</strong>, en échange d&#39;une visibilité. Il ne se confond pas avec un partenaire marketing, qui est facturé.</li><li>Le contrat se signe comme la Convention : lien email de 7 jours, lecture complète, code reçu à la même adresse, sans compte. edPage contre-signe selon le réglage de l&#39;Administrateur.</li><li>À la contre-signature, le contrat reçoit sa référence <code>CONVP-NB-AAAA-XXX</code> et son PDF scellé ; le partenariat devient <strong>actif</strong> et ses référentiels sont figés.</li><li>La visibilité (logo, lien, présentation, nature) reste modifiable et s&#39;affiche sur le site et dans le bloc « Partenaires » du cours Sève des cohortes concernées, mis à jour chaque heure.</li><li>Le partenariat prend fin le lendemain de sa date de fin. Une cohorte concernée le garde jusqu&#39;à sa propre fin si elle a commencé.</li></ul><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Un moteur unique (email, Sève, WhatsApp) envoie tous les rappels et alertes. L&#39;email part toujours ; Sève s&#39;ajoute pour les comptes ouverts dans Sève ; WhatsApp s&#39;ajoute pour les rappels de paiement et d&#39;admission, si le compte a un numéro. Un canal en échec n&#39;empêche pas les autres.</p><p>Les déclencheurs couvrent le paiement, l&#39;admission, les rôles, la certification, la présence, la formation B2B, la mise en relation, les événements, le financement d&#39;événement, les partenariats et les documents générés. Le détail est dans <a href="/kura-guide/guide/integrations.html#notifications">Intégrations</a>.</p>',25)])])}const g=t(s,[["render",r]]);export{m as __pageData,g as default};
